'use strict';
const paths={shield:'<path d="M12 3l8 3.5v5.8c0 5-8 8.7-8 8.7s-8-3.7-8-8.7V6.5z"/><path d="m8.5 12 2.5 2.5 4.5-5"/>',certificate:'<circle cx="12" cy="9" r="6"/><path d="m8 14-1 8 5-3 5 3-1-8"/>',check:'<path d="m5 12 4 4L19 6"/>',warning:'<path d="m12 3 10 18H2z"/><path d="M12 9v5m0 3h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',down:'<path d="m6 9 6 6 6-6"/>',up:'<path d="m6 15 6-6 6 6"/>',right:'<path d="m9 5 7 7-7 7"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-17a3 3 0 0 1 0 6m2 5a5 5 0 0 1 2 4v2"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v6h5M8 13h8m-8 4h5"/>',folder:'<path d="M3 6h7l2 3h9v12H3zM3 6V3h7l2 3h7v3"/>',clip:'<path d="m8 12 6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l9-9"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h3m3 0h3"/>',building:'<path d="m3 8 9-5 9 5H3zm2 2v8m5-8v8m4-8v8m5-8v8M3 21h18"/>',filter:'<path d="M3 6h5m4 0h9M3 12h11m4 0h3M3 18h2m4 0h12"/><circle cx="10" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="7" cy="18" r="2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',list:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 7h1m3 0h6M7 12h1m3 0h6M7 17h1m3 0h6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.file}</svg>`;
const data=SupplierData,records=data.records;
const state={page:'overview',filter:'All statuses',filterOpen:false,highlight:null,selected:null,detailTab:'overview',popover:null,action:null};
const notes=new Map(),risks=new Map();
let panelCloseTimer, lastFocus=null,actionFocus=null,popoverAnchor=null,openTimer,closeTimer,toastTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=data.formatDate;
const statusClass=s=>s==='Valid'?'valid':s==='Expired'?'expired':'review';
const badge=r=>{const s=data.status(r);return `<span class="status ${statusClass(s)}">${icon(s==='Valid'?'check':s==='Expired'?'warning':'clock')}${s}</span>`;};
const asset=(name,cls='')=>`<img class="figma-icon ${cls}" src="assets/${name}.svg" alt="">`;
const certIcon=r=>`<span class="cert-icon ${r.id.startsWith('cyber')?'cyber':''}">${icon(r.id.startsWith('cyber')?'shield':'certificate')}</span>`;
const visible=()=>records.filter(r=>state.filter==='All statuses'||data.status(r)===state.filter);
const sampleLine=()=>`Sample data · as of ${date(data.asOf)}`;
const sourceURL=r=>`#/documents?record=${encodeURIComponent(r.id)}&tab=evidence`;
function header(){return `<main class="workspace"><header class="supplier-head"><div class="supplier-identity"><div class="supplier-logo" aria-hidden="true">a.</div><div class="supplier-name"><h1>${data.supplier.name}</h1><span class="pill unclaimed">Unclaimed</span></div></div><div class="actions"><button class="btn" data-action="export">${icon('download')}Export</button><span class="approval">${icon('info')}Unapproved</span></div></header><nav class="tabs" aria-label="Supplier sections">${[['overview','Overview'],['activity','Activity'],['monitoring','External Monitoring'],['risks','Risks'],['documents','Documents'],['notes','Private Notes'],['about','About']].map(([id,label])=>`<button class="tab ${state.page===id?'active':''}" ${['overview','documents'].includes(id)?`data-page="${id}" aria-current="${state.page===id?'page':'false'}"`:'disabled title="Outside this certification preview"'}>${label}</button>`).join('')}</nav>`;}
function overview(){return `<section class="overview"><div class="info-banner">${icon('users')}<div><strong>No employee from this supplier is active on Risk Ledger yet</strong><p>They are included in your supplier list, but supplier assessment data is not available.</p></div></div><div class="section-heading"><div class="section-title">${icon('certificate')}<h2>Security certifications</h2></div></div><div class="cert-grid">${records.map(r=>`<button class="cert-card" data-summary="${r.id}" data-document="${r.id}" aria-label="View ${r.name} in Documents">${certIcon(r)}<div><span class="name">${r.name}</span>${badge(r)}</div></button>`).join('')}</div><div class="cert-note">${icon('info')}Validity reflects certificate dates. Discovered evidence has not been reviewed.</div><section class="monitoring"><div class="section-heading"><div class="section-title">${icon('target')}Monitoring</div><span class="quiet optional">Latest scan · ${date(data.monitoring.asOf)}</span></div><div class="metrics"><div class="metric"><div class="metric-label">Latest findings</div><div class="metric-value">${data.monitoring.severity.reduce((a,s)=>a+s.count,0)}</div></div><div class="metric"><div class="metric-label">No. of assets</div><div class="metric-value">${data.monitoring.assets}</div></div><div class="metric"><div class="metric-label">Latest findings per severity</div><div class="severity">${data.monitoring.severity.map(s=>`<div><div class="severity-label">${s.label}</div><span class="severity-count ${s.label.toLowerCase()}">${s.count}</span></div>`).join('')}</div></div></div></section><p class="snapshot-label">${sampleLine()}</p></section>`;}
function documents(){const list=visible(),n=data.counts();return `<section class="documents"><div><header class="content-heading"><h2>Security certifications</h2><p>Discovered certificates and claims for ${data.supplier.name}.</p><div class="discovered-summary"><span class="found">${icon('spark')}${n.total} records discovered</span></div></header><div class="table-toolbar"><div class="toolbar-left"><button class="btn" id="filter-button" data-action="filter" aria-expanded="${state.filterOpen}" aria-controls="filter-menu">${icon('filter')}Add filter</button>${state.filter!=='All statuses'?`<span class="filter-chip">${state.filter}<button data-filter="All statuses" aria-label="Clear status filter">${icon('close')}</button></span>`:''}</div><span class="quiet">${list.length} ${list.length===1?'record':'records'}</span>${state.filterOpen?`<div class="filter-menu" id="filter-menu"><strong>Certificate validity</strong>${['All statuses','Valid','Expired','Needs review'].map(s=>`<button data-filter="${s}" class="${s===state.filter?'selected':''}">${s}${s===state.filter?icon('check'):''}</button>`).join('')}</div>`:''}</div><div class="table-wrap"><table aria-label="Discovered security certifications"><thead><tr><th>Certification</th><th>Validity</th><th>Expiry date</th><th>Source</th></tr></thead><tbody>${list.map(r=>`<tr class="data-row ${r.id===state.highlight?'highlight':''}" data-row="${r.id}"><td><div class="row-cert">${certIcon(r)}<div><button class="row-open" data-record="${r.id}">${r.name}</button><div class="row-description">${r.summary}</div></div></div></td><td><button class="status-trigger" data-summary="${r.id}" aria-haspopup="dialog" aria-expanded="false" aria-label="${r.name} summary">${badge(r)}</button></td><td class="expiry-cell">${date(r.expiresOn)}</td><td class="source-cell"><div class="source-wrap">${r.source.type}${icon('right')}</div></td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty">No certifications match this filter.</div>':''}<div class="table-footer"><span>Showing ${list.length} of ${records.length} records</span><span>Certificate dates only · evidence not reviewed</span></div></div></section>`;}
function render(){hidePopover();document.getElementById('app').innerHTML=header()+(state.page==='overview'?overview():documents())+'</main>';document.title=`${state.page==='overview'?'Supplier overview':'Security certifications'} · ${data.supplier.name}`;}
function setPage(page,highlight=null){if(state.selected)closeRecord();state.page=page;state.highlight=highlight;state.filter='All statuses';state.filterOpen=false;history.replaceState(null,'',page==='documents'?'#/documents':'#/overview');render();}
function field(label,value,type){return `<div class="detail-field"><div class="field-label">${icon(type)}${label}</div><div class="field-value">${esc(value||'Not found')}</div></div>`;}
function recordActions(r){return `<div class="tooltip-actions"><button class="btn" data-risk="${r.id}">${asset('crisis-alert')}Open risk</button><button class="btn" data-note="${r.id}">${asset('add')}Add private note</button></div>`;}
function activity(r){const rr=risks.get(r.id)||[],nn=notes.get(r.id)||[];return `<section class="record-activity"><div class="detail-divider"></div><h3>Risks & private notes</h3>${rr.map(x=>`<div class="activity-entry"><strong>${esc(x.title)}</strong><span class="quiet">${esc(x.severity)} risk · ${esc(x.created)}</span><p>${esc(x.description)}</p></div>`).join('')}${nn.map(x=>`<div class="activity-entry"><span class="quiet">Private note · ${esc(x.created)}</span><p>${esc(x.text)}</p></div>`).join('')}${!rr.length&&!nn.length?'<p class="evidence-caption">No risks or notes added for this certification.</p>':''}${recordActions(r)}<p class="evidence-caption">Risks and notes are kept for this preview session only.</p></section>`;}
function drawerContent(r){const s=data.status(r),explanation=s==='Expired'?`Expired on ${date(r.expiresOn)}. A renewed certificate has not been found.`:s==='Needs review'?'Website claim only. No certificate was found to establish the issuer, scope or validity.':`Within its stated validity period as of ${date(data.asOf)}. Evidence and supplier coverage still need review.`;if(state.detailTab==='evidence')return `<div class="evidence-view"><div class="detail-title">${certIcon(r)}<div><p>Source evidence</p><h2>${r.name}</h2></div></div><h3>${r.source.kind==='claim'?'Website claim':'Discovered document'}</h3><dl class="source-record"><dt>Source</dt><dd>${r.source.type}</dd><dt>Document</dt><dd>${r.source.file||'No certificate found'}</dd><dt>Discovered on</dt><dd>${date(r.source.discoveredOn)}</dd><dt>Evidence review</dt><dd>Not reviewed</dd><dt>Legal entity in evidence</dt><dd>${r.legalEntity||'Not found'}</dd><dt>Scope in evidence</dt><dd>${r.scope||'Not found'}</dd></dl><p>This is sample evidence for the interactive preview. No real certificate, supplier website or uploaded file is attached.</p></div>`;return `<div class="detail-title">${certIcon(r)}<div><p>Security certification</p><h2>${r.name}</h2></div></div><div class="status-notice ${statusClass(s)}">${badge(r)}<p>${explanation}</p></div><div class="detail-fields">${field('Certificate name',r.name,'certificate')}${field('Legal entity',r.legalEntity,'building')}${field('Issued on',date(r.issuedOn),'calendar')}${field('Expiry date',date(r.expiresOn),'calendar')}${field('Issuing body',r.issuer,'building')}${field('Scope',r.scope,'target')}${field('Certificate ID',r.certificateId,'globe')}${field('Evidence review','Not reviewed','info')}</div><div class="detail-divider"></div><h3>Source evidence</h3><button class="evidence-card" data-detail-tab="evidence" aria-label="Review source evidence for ${r.name}"><span class="file-icon">${icon('file')}</span><div><h3>${r.source.file||'Website claim'}</h3><p>${r.source.type}</p></div><span class="file-meta">${icon('right')}</span></button><p class="evidence-caption">Discovered ${date(r.source.discoveredOn)} · ${r.source.kind==='certificate'?'Certificate found':'Certificate not found'}</p>${activity(r)}`;}
function syncSelection(){document.querySelectorAll('[data-row]').forEach(row=>{const active=row.dataset.row===state.selected;row.classList.toggle('highlight',active);row.setAttribute('aria-selected',String(active));});}
function renderDrawer(focus=true){clearTimeout(panelCloseTimer);hidePopover();const root=document.getElementById('drawer-root');document.body.classList.toggle('panel-open',!!state.selected);if(!state.selected){root.querySelector('.drawer')?.classList.add('panel-closing');panelCloseTimer=setTimeout(()=>{if(!state.selected)root.innerHTML='';},matchMedia('(prefers-reduced-motion: reduce)').matches?0:280);syncSelection();return;}const r=data.get(state.selected),list=visible(),index=list.findIndex(x=>x.id===r.id);let panel=root.querySelector('.drawer');const fresh=!panel;if(fresh){root.innerHTML=`<aside class="drawer" role="region"><header class="drawer-header"><button class="icon-btn" data-step="-1" aria-label="Previous certification">${icon('up')}</button><button class="icon-btn" data-step="1" aria-label="Next certification">${icon('down')}</button><span class="drawer-counter"></span><button class="icon-btn drawer-close" data-action="close" aria-label="Close details">${icon('close')}</button></header><nav class="drawer-tabs" aria-label="Certification detail sections"><button class="drawer-tab" data-detail-tab="overview">Overview</button><button class="drawer-tab" data-detail-tab="evidence">Source evidence</button></nav><div class="drawer-body"></div><footer class="drawer-footer">${icon('info')}${sampleLine()}</footer></aside>`;panel=root.querySelector('.drawer');}panel.classList.remove('panel-closing');panel.setAttribute('aria-label',`${r.name} details`);panel.querySelector('[data-step="-1"]').disabled=index<=0;panel.querySelector('[data-step="1"]').disabled=index>=list.length-1;panel.querySelector('.drawer-counter').textContent=`${index+1} of ${list.length} records`;panel.querySelectorAll('.drawer-tab').forEach(t=>{const active=t.dataset.detailTab===state.detailTab;t.classList.toggle('active',active);t.setAttribute('aria-pressed',String(active));});const body=panel.querySelector('.drawer-body');body.getAnimations?.().forEach(a=>a.cancel());body.innerHTML=drawerContent(r);body.scrollTop=0;if(!fresh&&!matchMedia('(prefers-reduced-motion: reduce)').matches)body.animate([{opacity:0},{opacity:1}],{duration:180,easing:'ease-out'});syncSelection();if(focus&&fresh)panel.querySelector('.drawer-close').focus();}
function openRecord(id,tab='overview'){data.get(id);hidePopover();const fresh=!state.selected;if(fresh)lastFocus=document.activeElement;if(state.page!=='documents')setPage('documents');if(!visible().some(r=>r.id===id)){state.filter='All statuses';render();}state.selected=id;state.highlight=id;state.detailTab=tab;renderDrawer(fresh);}
function closeRecord(){state.selected=null;state.highlight=null;renderDrawer();history.replaceState(null,'',state.page==='documents'?'#/documents':'#/overview');lastFocus?.isConnected&&lastFocus.focus();}
function stepRecord(step){const list=visible(),i=list.findIndex(r=>r.id===state.selected);if(!list[i+step])return;state.selected=list[i+step].id;state.highlight=state.selected;state.detailTab='overview';renderDrawer(false);}
function hidePopover(){clearTimeout(openTimer);clearTimeout(closeTimer);document.getElementById('popover-root').innerHTML='';popoverAnchor?.setAttribute('aria-expanded','false');state.popover=null;popoverAnchor=null;}
function showPopover(id,anchor,focus=false){if(state.selected||state.action)return;clearTimeout(openTimer);clearTimeout(closeTimer);if(state.popover===id&&popoverAnchor===anchor){if(focus)document.querySelector('.rich-tooltip a')?.focus();return;}hidePopover();const r=data.get(id);state.popover=id;popoverAnchor=anchor;anchor.setAttribute('aria-expanded','true');document.getElementById('popover-root').innerHTML=`<section class="rich-tooltip" role="dialog" aria-label="${r.name} summary"><div class="tooltip-content"><h3>${r.name}</h3><dl><div><dt>Expiry date</dt><dd>${date(r.expiresOn)}</dd></div><div><dt>Issuing body</dt><dd>${r.issuer||'Not found'}</dd></div><div><dt>Source</dt><dd><a class="cert-source" href="${sourceURL(r)}" target="_blank" rel="noopener">Certification source${asset('open-in-new')}</a></dd></div></dl></div>${recordActions(r)}</section>`;const box=document.querySelector('.rich-tooltip'),rect=anchor.getBoundingClientRect(),width=box.offsetWidth,height=box.offsetHeight;box.style.left=Math.max(12,Math.min(rect.left,innerWidth-width-12))+'px';const below=rect.bottom+8;box.style.top=Math.max(12,below+height>innerHeight-12?rect.top-height-8:below)+'px';if(focus)box.querySelector('a').focus();}
function scheduleHide(){clearTimeout(closeTimer);closeTimer=setTimeout(()=>{const box=document.querySelector('.rich-tooltip');if(!box?.contains(document.activeElement)&&document.activeElement!==popoverAnchor)hidePopover();},180);}
function openAction(kind,id){data.get(id);actionFocus=document.activeElement;hidePopover();state.action={kind,id};const r=data.get(id);document.getElementById('action-root').innerHTML=`<div class="action-backdrop" data-action="cancel-action"></div><section class="action-dialog" role="dialog" aria-modal="true" aria-labelledby="action-title"><header><h2 id="action-title">${kind==='risk'?'Open risk':'Add private note'}</h2><button class="icon-btn" data-action="cancel-action" aria-label="Close form">${icon('close')}</button></header><p class="form-context">${r.name} · ${data.supplier.name}</p><form id="record-form">${kind==='risk'?`<label>Risk title<input name="title" maxlength="160" required value="Review ${r.name} evidence"></label><label>Severity<select name="severity"><option>Low</option><option selected>Medium</option><option>High</option><option>Critical</option></select></label><label>Description<textarea name="description" rows="4" maxlength="2000" required></textarea></label>`:'<label>Private note<textarea name="text" rows="5" maxlength="2000" required placeholder="Add context for your team"></textarea></label>'}<p class="evidence-caption">Saved for this preview session only. Nothing is sent to the supplier.</p><div class="form-actions"><button type="button" class="btn" data-action="cancel-action">Cancel</button><button class="btn teal" type="submit">${kind==='risk'?'Save risk':'Save note'}</button></div></form></section>`;document.getElementById('app').inert=true;document.getElementById('drawer-root').inert=true;document.body.style.overflow='hidden';document.querySelector('.action-dialog input,.action-dialog textarea').focus();}
function closeAction(){state.action=null;document.getElementById('action-root').innerHTML='';document.getElementById('drawer-root').inert=false;document.getElementById('app').inert=false;document.body.style.overflow='';actionFocus?.focus();}
function notify(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600);}
function exportCSV(){const csv=[['Certification','Validity','Expiry date','Issued on','Issuing body','Legal entity','Certificate ID','Source','Document','Scope','As of','Evidence review'],...visible().map(r=>[r.name,data.status(r),date(r.expiresOn),date(r.issuedOn),r.issuer,r.legalEntity,r.certificateId,r.source.type,r.source.file,r.scope,date(data.asOf),'Not reviewed'])].map(row=>row.map(v=>'"'+String(v??'Not found').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='atlas-security-certifications-sample.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Certification records exported');}
function applyRoute(){const [route,query='']=location.hash.slice(2).split('?'),q=new URLSearchParams(query);state.page=route==='documents'?'documents':'overview';state.selected=null;render();renderDrawer(false);const id=q.get('record');if(id&&records.some(r=>r.id===id))openRecord(id,q.get('tab')==='evidence'?'evidence':'overview');}
function focusTrap(e,selector){const f=[...document.querySelectorAll(`${selector} button:not(:disabled),${selector} a[href],${selector} input,${selector} select,${selector} textarea`)];if(!f.length)return;const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
function bindEvents(){
document.addEventListener('pointerover',e=>{const anchor=e.target.closest('[data-summary]');if(anchor&&!anchor.contains(e.relatedTarget)){clearTimeout(closeTimer);openTimer=setTimeout(()=>showPopover(anchor.dataset.summary,anchor),120);}if(e.target.closest('.rich-tooltip'))clearTimeout(closeTimer);});
document.addEventListener('pointerout',e=>{const from=e.target.closest('[data-summary],.rich-tooltip');if(from&&!from.contains(e.relatedTarget)){clearTimeout(openTimer);if(!e.relatedTarget?.closest?.('.rich-tooltip,[data-summary]'))scheduleHide();}});
document.addEventListener('focusin',e=>{const anchor=e.target.closest('[data-summary]');if(anchor)showPopover(anchor.dataset.summary,anchor);else if(!e.target.closest('.rich-tooltip'))hidePopover();});
document.addEventListener('click',e=>{const t=e.target.closest('button,[data-action]');if(!e.target.closest('.rich-tooltip,[data-summary]'))hidePopover();if(t){if(t.dataset.page)setPage(t.dataset.page);if(t.dataset.record)openRecord(t.dataset.record);if(t.dataset.document)setPage('documents',t.dataset.document);else if(t.dataset.summary)showPopover(t.dataset.summary,t,true);if(t.dataset.filter){state.filter=t.dataset.filter;state.filterOpen=false;if(state.selected&&!visible().some(r=>r.id===state.selected))closeRecord();render();syncSelection();document.getElementById('filter-button').focus();}if(t.dataset.step)stepRecord(Number(t.dataset.step));if(t.dataset.detailTab){state.detailTab=t.dataset.detailTab;renderDrawer(false);document.querySelector(`.drawer-tab[data-detail-tab="${state.detailTab}"]`).focus();}if(t.dataset.risk)openAction('risk',t.dataset.risk);if(t.dataset.note)openAction('note',t.dataset.note);if(t.dataset.action==='filter'){state.filterOpen=!state.filterOpen;render();(document.querySelector('.filter-menu button')||document.getElementById('filter-button')).focus();}if(t.dataset.action==='close')closeRecord();if(t.dataset.action==='cancel-action')closeAction();if(t.dataset.action==='export')exportCSV();return;}const row=e.target.closest('[data-row]');if(row)openRecord(row.dataset.row);else if(state.filterOpen&&!e.target.closest('.filter-menu')){state.filterOpen=false;render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='record-form')return;e.preventDefault();const form=new FormData(e.target),a=state.action,created=new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date());if(a.kind==='risk'){const title=form.get('title').trim(),description=form.get('description').trim();if(!title||!description)return;risks.set(a.id,[...(risks.get(a.id)||[]),{title,description,severity:form.get('severity'),created}]);}else{const text=form.get('text').trim();if(!text)return;notes.set(a.id,[...(notes.get(a.id)||[]),{text,created}]);}closeAction();setPage('documents');openRecord(a.id);notify(a.kind==='risk'?'Risk saved for this preview session':'Private note saved for this preview session');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.action)closeAction();else if(state.popover){const a=popoverAnchor;hidePopover();a?.focus();hidePopover();}else if(state.selected)closeRecord();else if(state.filterOpen){state.filterOpen=false;render();document.getElementById('filter-button').focus();}}if(e.key==='Tab'){if(state.action)focusTrap(e,'.action-dialog');}});
window.addEventListener('hashchange',applyRoute);window.addEventListener('resize',hidePopover);document.addEventListener('scroll',e=>{if(!e.target.closest?.('.rich-tooltip'))hidePopover();},true);
}
bindEvents();applyRoute();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_certifications',description:'Read the shared illustrative certification snapshot and current selection.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({asOf:data.asOf,records:records.map(data.summary),counts:data.counts(),page:state.page,filter:state.filter,selected:state.selected})},{name:'open_certification_details',description:'Open a certification in the visible detail panel.',inputSchema:{type:'object',properties:{id:{type:'string',enum:records.map(r=>r.id)}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{data.get(input?.id);setPage('documents');openRecord(input.id);return {selected:state.selected,page:state.page};}}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
